import subprocess,json,pathlib,datetime,hashlib
root=pathlib.Path.cwd();job=root/'target/p9/native486-capacity-bound/checked';job.mkdir(exist_ok=True);logs=job/'logs';logs.mkdir(exist_ok=True)
def inventory():
 names=set(json.loads((root/'target/p9/native480-admission/linux/SOURCE.json').read_text())['sha256'])
 names.update(subprocess.check_output(['git','ls-files','--others','--exclude-standard','--','src','tests','examples','benchmarks/matched/src'],text=True).splitlines())
 return{n:{'sha256':hashlib.sha256((root/n).read_bytes()).hexdigest(),'mode':oct((root/n).stat().st_mode&0o7777)}for n in sorted(names)}
commands=[('fmt',['cargo','+stable','fmt','--all']),('application-all',['cargo','+stable','test','--locked','--offline','--all-features','--test','application','--','--test-threads=1']),('application-unit-all',['cargo','+stable','test','--locked','--offline','--all-features','--lib','application::','--','--test-threads=1']),('clients-all',['cargo','+stable','test','--locked','--offline','--all-features','--test','effect_owner','client_admission::','--','--test-threads=1']),('providers-all',['cargo','+stable','test','--locked','--offline','--all-features','--test','provider_conformance','--','--test-threads=1']),('application-core',['cargo','+stable','test','--locked','--offline','--no-default-features','--test','application','--','--test-threads=1']),('application-unit-core',['cargo','+stable','test','--locked','--offline','--no-default-features','--lib','application::','--','--test-threads=1']),('clients-core',['cargo','+stable','test','--locked','--offline','--no-default-features','--test','effect_owner','client_admission::','--','--test-threads=1']),('providers-core',['cargo','+stable','test','--locked','--offline','--no-default-features','--test','provider_conformance','--','--test-threads=1']),('services',['cargo','+stable','test','--locked','--offline','--all-features','--test','counter_service','three_','--','--test-threads=1']),('matched',['cargo','+stable','test','--manifest-path','benchmarks/matched/Cargo.toml','--locked','--offline','--','--test-threads=1']),('metadata',['node','validation/check-provider-conformance.mjs']),('metadata-negative',['node','validation/check-provider-conformance.test.mjs']),('strict',['sh','.githooks/pre-push'])]
receipts=[];before=None
for name,argv in commands:
 (job/'STAGE').write_text(name+'\n');start=datetime.datetime.now(datetime.timezone.utc).isoformat();print('START',name,flush=True)
 with(logs/(name+'.stdout')).open('wb')as out,(logs/(name+'.stderr')).open('wb')as err:r=subprocess.run(argv,stdout=out,stderr=err)
 (logs/(name+'.exit')).write_text(str(r.returncode)+'\n');receipts.append({'name':name,'argv':argv,'start_utc':start,'end_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'actual_exit':r.returncode});(job/'COMMANDS.json').write_text(json.dumps(receipts,indent=2)+'\n');print('END',name,r.returncode,flush=True)
 if r.returncode:raise SystemExit(r.returncode)
 if name=='fmt':before=inventory();(job/'INPUTS_BEFORE.json').write_text(json.dumps(before,indent=2)+'\n')
after=inventory();assert before==after;(job/'INPUTS_AFTER.json').write_text(json.dumps(after,indent=2)+'\n');(job/'STATUS').write_text('0\n');(job/'STAGE').write_text('DONE\n');print('DONE',len(after),flush=True)
